using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

public class AppHostTests
{
    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        await app.StartAsync();
        await app.WaitForResources().WaitAsync(TimeSpan.FromSeconds(30));

        // Verify the app model was created without errors
        Assert.NotNull(app);
    }

    [Fact]
    public async Task AppHost_ResourcesResolve()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await builder.BuildAsync();
        var model = app.Services.GetRequiredService<Aspire.Hosting.DistributedApplicationModel>();

        // The app host should produce a valid resource graph
        Assert.NotNull(model);
    }
}

